package com.utewedding.app.domain.entity;
import jakarta.persistence.*;import java.util.UUID;
@Entity @Table(name="accounting_document_lines") public class AccountingDocumentLineEntity{
 @Id@GeneratedValue(strategy=GenerationType.UUID)private UUID id;@Column(name="document_id",nullable=false)private UUID documentId;@Column(name="seller_id")private UUID sellerId;@Column(name="order_item_id")private UUID orderItemId;@Column(name="product_id")private UUID productId;@Column(name="product_name",nullable=false)private String productName;@Column(nullable=false)private int quantity;@Column(name="unit_price",nullable=false)private long unitPrice;@Column(name="product_discount",nullable=false)private long productDiscount;@Column(name="voucher_discount",nullable=false)private long voucherDiscount;@Column(name="line_total",nullable=false)private long lineTotal;
 public UUID getId(){return id;}public UUID getDocumentId(){return documentId;}public void setDocumentId(UUID v){documentId=v;}public UUID getSellerId(){return sellerId;}public void setSellerId(UUID v){sellerId=v;}public UUID getOrderItemId(){return orderItemId;}public void setOrderItemId(UUID v){orderItemId=v;}public UUID getProductId(){return productId;}public void setProductId(UUID v){productId=v;}public String getProductName(){return productName;}public void setProductName(String v){productName=v;}public int getQuantity(){return quantity;}public void setQuantity(int v){quantity=v;}public long getUnitPrice(){return unitPrice;}public void setUnitPrice(long v){unitPrice=v;}public long getProductDiscount(){return productDiscount;}public void setProductDiscount(long v){productDiscount=v;}public long getVoucherDiscount(){return voucherDiscount;}public void setVoucherDiscount(long v){voucherDiscount=v;}public long getLineTotal(){return lineTotal;}public void setLineTotal(long v){lineTotal=v;}
}
